import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.text.*;import java.math.*;
public class Study {
 public record Raw(long line,String text){}public record Summary(long count,double sum,OptionalDouble average){}
 public static class BadRecord extends Exception {private final long line;public BadRecord(long line,Throwable cause){super("Ошибка записи в строке "+line,cause);this.line=line;}public long line(){return line;}}
 public static List<Raw> read(Path path)throws IOException {var rows=new ArrayList<Raw>();try(var reader=Files.newBufferedReader(path,StandardCharsets.UTF_8)){String text;long line=0;while((text=reader.readLine())!=null)rows.add(new Raw(++line,text));}return rows;}
 private static BigDecimal number(Raw row)throws BadRecord {try{String[] fields=row.text().split("\t",-1);if(fields.length!=2||fields[0].isEmpty()||fields[1].isEmpty())throw new IllegalArgumentException("Ожидаются два непустых поля");Locale locale=new Locale.Builder().setLanguageTag(fields[1]).build();NumberFormat format=NumberFormat.getNumberInstance(locale);if(format instanceof DecimalFormat decimal)decimal.setParseBigDecimal(true);ParsePosition position=new ParsePosition(0);Number value=format.parse(fields[0],position);if(value==null)throw new IllegalArgumentException("Число не разобрано целиком");if(!Double.isFinite(value.doubleValue()))throw new ArithmeticException("Число вне конечного double");return value instanceof BigDecimal decimal?decimal:new BigDecimal(value.toString());}catch(RuntimeException cause){throw new BadRecord(row.line(),cause);}}
 public static Summary analyze(List<Raw> rows)throws BadRecord {BigDecimal sum=BigDecimal.ZERO;for(Raw row:rows)sum=sum.add(number(row));if(rows.isEmpty())return new Summary(0,0,OptionalDouble.empty());double total=sum.doubleValue();double average=sum.divide(BigDecimal.valueOf(rows.size()),MathContext.DECIMAL128).doubleValue();if(!Double.isFinite(total)||!Double.isFinite(average))throw new BadRecord(rows.getLast().line(),new ArithmeticException("Итог вне конечного double"));return new Summary(rows.size(),total,OptionalDouble.of(average));}
 void main(String[] args){try{Summary result=analyze(read(Path.of(args[0])));if(result.average().isEmpty())System.out.println("Нет данных");else System.out.println("Сумма "+result.sum()+", среднее "+result.average().getAsDouble());}catch(BadRecord e){System.err.println(e.getMessage()+": "+e.getCause());}catch(IOException e){System.err.println("Ошибка чтения: "+e.getMessage());}}
}
